PREFIX brick: <http://brickschema.org/brick#>
PREFIX ref: <http://brickschema.org/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?lbl ?class ?ts WHERE {
  ?s a ?class .
  OPTIONAL { ?s rdfs:label ?lbl }
  FILTER(?lbl IN ("Perimeter_ZN_3","Perimeter_ZN_4"))
  OPTIONAL { ?s ref:hasTimeseriesId ?ts }
} LIMIT 50

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <http://brickschema.org/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?lbl ?class ?ts ?lbl2 WHERE {
  ?s rdfs:label "Perimeter_ZN_3" .
  ?s ?p ?o .
  OPTIONAL { ?o rdfs:label ?lbl2 }
  OPTIONAL { ?o ref:hasTimeseriesId ?ts }
  FILTER(?p != rdfs:label && ?p != rdf:type)
} LIMIT 50

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <http://brickschema.org/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT ?subject ?pred ?obj ?objlbl WHERE {
  ?s rdfs:label "Perimeter_ZN_3" .
  { ?s ?pred ?obj . }
  OPTIONAL { ?obj rdfs:label ?objlbl }
} LIMIT 100

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <http://brickschema.org/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT ?zonelbl ?zonedir ?pointlbl ?pclass ?ts WHERE {
  ?z rdfs:label ?zonelbl .
  FILTER(?zonelbl IN ("Perimeter_ZN_3","Perimeter_ZN_4"))
  ?z brick:hasPoint ?p .
  OPTIONAL { ?p rdfs:label ?pointlbl }
  OPTIONAL { ?p a ?pclass }
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
  FILTER(str(?pclass) LIKE "%Temperature_Sensor%" || str(?p) LIKE "%Temperature_Sensor%")
}

SELECT DISTINCT ?zonelbl ?p ?ts WHERE {
  ?z rdfs:label ?zonelbl .
  ?z <https://brickschema.org/schema/Brick#hasPoint> ?p .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
}

